import React, { useState } from 'react';
import './MenuItems.css';

const MenuItems = ({ category, onAddToCart }) => {
  const [selectedItem, setSelectedItem] = useState(null);
  const [selectedOptions, setSelectedOptions] = useState({});

  const menuItems = [
    {
      id: 1,
      name: 'Bulgogi Rice Bowl',
      description: 'Marinated beef with steamed rice and vegetables',
      price: 18.50,
      image: 'https://images.unsplash.com/photo-1553909489-cd47e0ef937f?w=300&h=200&fit=crop',
      options: {
        size: [
          { id: 'regular', name: 'Regular', price: 0 },
          { id: 'large', name: 'Large', price: 3.00 }
        ],
        spice: [
          { id: 'mild', name: '보통', price: 0 },
          { id: 'spicy', name: '매움', price: 0 }
        ],
        toppings: [
          { id: 'cheese', name: 'Extra Cheese', price: 2.00 },
          { id: 'egg', name: 'Fried Egg', price: 1.50 }
        ]
      }
    },
    {
      id: 2,
      name: 'Kimchi Fried Rice',
      description: 'Spicy fermented cabbage fried rice with egg',
      price: 15.50,
      image: 'https://images.unsplash.com/photo-1498654896293-37aacf113fd9?w=300&h=200&fit=crop',
      options: {
        size: [
          { id: 'regular', name: 'Regular', price: 0 },
          { id: 'large', name: 'Large', price: 2.50 }
        ],
        spice: [
          { id: 'mild', name: '보통', price: 0 },
          { id: 'spicy', name: '매움', price: 0 }
        ]
      }
    },
    {
      id: 3,
      name: 'Korean BBQ Set',
      description: 'Grilled pork belly with banchan and rice',
      price: 24.90,
      image: 'https://images.unsplash.com/photo-1529692236671-f1f6cf9683ba?w=300&h=200&fit=crop',
      options: {}
    }
  ];

  const openModal = (item, e) => {
    e.stopPropagation(); // 카드 클릭 이벤트 방지
    setSelectedItem(item);
    // 기본 옵션 설정
    const defaultOptions = {};
    Object.keys(item.options).forEach(optionType => {
      if (item.options[optionType]?.length > 0) {
        defaultOptions[optionType] = item.options[optionType][0].id;
      }
    });
    setSelectedOptions(defaultOptions);
  };

  const closeModal = () => {
    setSelectedItem(null);
    setSelectedOptions({});
  };

  const handleOptionChange = (optionType, optionId) => {
    if (optionType === 'toppings') {
      setSelectedOptions(prev => ({
        ...prev,
        [optionType]: prev[optionType] ? 
          (prev[optionType].includes(optionId) 
            ? prev[optionType].filter(id => id !== optionId)
            : [...prev[optionType], optionId]
          ) : [optionId]
      }));
    } else {
      setSelectedOptions(prev => ({
        ...prev,
        [optionType]: optionId
      }));
    }
  };

  const calculateTotalPrice = () => {
    if (!selectedItem) return 0;

    let total = selectedItem.price;
    Object.keys(selectedOptions).forEach(optionType => {
      const selectedValue = selectedOptions[optionType];
      const options = selectedItem.options[optionType];
      if (!options) return;

      if (Array.isArray(selectedValue)) {
        selectedValue.forEach(valueId => {
          const option = options.find(opt => opt.id === valueId);
          if (option) total += option.price;
        });
      } else {
        const option = options.find(opt => opt.id === selectedValue);
        if (option) total += option.price;
      }
    });
    return total;
  };

  const addToCartWithOptions = () => {
    if (!selectedItem) return;
    const cartItem = {
      ...selectedItem,
      selectedOptions,
      finalPrice: calculateTotalPrice(),
      cartId: Date.now()
    };
    onAddToCart?.(cartItem);
    closeModal();
  };

  const addDirectToCart = (item) => {
    const cartItem = {
      ...item,
      selectedOptions: {},
      finalPrice: item.price,
      cartId: Date.now()
    };
    onAddToCart?.(cartItem);
  };

  // ESC 키로 모달 닫기
  React.useEffect(() => {
    const handleEsc = (event) => {
      if (event.keyCode === 27) closeModal();
    };
    if (selectedItem) {
      document.addEventListener('keydown', handleEsc);
    }
    return () => document.removeEventListener('keydown', handleEsc);
  }, [selectedItem]);

  return (
    <div className="menu-items">
      {/* Menu Items - List Style */}
      <div className="menu-list-section">
        <h3>Menu Items - List Style</h3>
        <div className="menu-list">
          {menuItems.map(item => (
            <div key={`list-${item.id}`} className="menu-list-item" onClick={() => addDirectToCart(item)}>
              <img src={item.image} alt={item.name} className="list-item-image" />
              <div className="list-item-content">
                <div className="list-item-header">
                  <span className="list-item-name">{item.name}</span>
                  <span className="list-item-price">RM {item.price.toFixed(2)}</span>
                </div>
                <p className="list-item-description">{item.description}</p>
                <p className="list-item-ingredients">Ingredients: Chicken, potatoes, oil, etc</p>
              </div>
              {Object.keys(item.options).length > 0 && (
                <button 
                  className="list-options-btn"
                  onClick={(e) => openModal(item, e)}
                >
                  Options
                </button>
              )}
            </div>
          ))}
        </div>
      </div>

      {/* Menu Items - Card Style */}
      <div className="menu-card-section">
        <h3>Menu Items - Card Style</h3>
        <div className="menu-grid">
          {menuItems.map(item => (
            <div key={`card-${item.id}`} className="menu-item-card" onClick={() => addDirectToCart(item)}>
              <div className="menu-item-image">
                <img src={item.image} alt={item.name} />
              </div>
              <div className="menu-item-content">
                <h3 className="menu-item-name">{item.name}</h3>
                <p className="menu-item-description">{item.description}</p>
                <p className="menu-item-ingredients">Ingredients: Chicken, potatoes, oil, etc</p>
                <div className="menu-item-price">RM {item.price.toFixed(2)}</div>
              </div>

              {/* Options 버튼 (카드 우측 하단) */}
              {Object.keys(item.options).length > 0 && (
                <button 
                  className="btn-options-card"
                  onClick={(e) => openModal(item, e)}
                >
                  Options
                </button>
              )}
            </div>
          ))}
        </div>
      </div>

      {/* 모달 팝업 - 심플하게 수정 */}
      {selectedItem && (
        <div className="modal-overlay" onClick={closeModal}>
          <div className="modal-popup-simple" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header-simple">
              <div className="modal-title-price">
                <span className="modal-title">{selectedItem.name}</span>
                <span className="modal-base-price">Base: RM {selectedItem.price.toFixed(2)}</span>
              </div>
              <button className="modal-close-btn" onClick={closeModal}>×</button>
            </div>

            <div className="modal-body-simple">
              {Object.entries(selectedItem.options).map(([optionType, options]) => (
                <div key={optionType} className="modal-option-group-simple">
                  <div className="modal-option-title">
                    {optionType === 'size' && 'Size:'}
                    {optionType === 'spice' && '맵기:'}
                    {optionType === 'toppings' && '토핑:'}
                  </div>

                  {optionType === 'toppings' ? (
                    <div className="modal-checkboxes">
                      {options.map(option => (
                        <label key={option.id} className="modal-checkbox">
                          <input
                            type="checkbox"
                            checked={(selectedOptions[optionType] || []).includes(option.id)}
                            onChange={() => handleOptionChange(optionType, option.id)}
                          />
                          <span>{option.name} (+RM {option.price.toFixed(2)})</span>
                        </label>
                      ))}
                    </div>
                  ) : (
                    <div className="modal-radio-buttons">
                      {options.map(option => (
                        <button
                          key={option.id}
                          className={`modal-option-btn ${selectedOptions[optionType] === option.id ? 'selected' : ''}`}
                          onClick={() => handleOptionChange(optionType, option.id)}
                        >
                          {option.name}
                          {option.price > 0 && ` (+RM ${option.price.toFixed(2)})`}
                        </button>
                      ))}
                    </div>
                  )}
                </div>
              ))}
            </div>

            <div className="modal-footer-simple">
              <div className="modal-total">Total: RM {calculateTotalPrice().toFixed(2)}</div>
              <button className="modal-add-btn" onClick={addToCartWithOptions}>
                Add to Cart
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default MenuItems;
